-- =====================================================================
-- V23: Nạp Bảng thành phần thực phẩm Việt Nam 2007 vào nutrition_foods
--
-- Nguồn: Viện Dinh dưỡng - Bộ Y tế (2007). Bảng thành phần thực phẩm Việt Nam
--        (Vietnamese Food Composition Table). Nhà xuất bản Y học, Hà Nội.
-- Sử dụng trong phạm vi đồ án học thuật, có trích dẫn nguồn. Phát hành thương mại
-- cần xin phép Viện Dinh dưỡng.
--
-- Quy ước:
--  * Giá trị trên 100 g PHẦN ĂN ĐƯỢC; waste_pct = tỉ lệ thải bỏ (%) khi sơ chế.
--  * "-" trong sách (không có số liệu) -> NULL. Không tự điền hay suy ra.
--  * Sách đo chất xơ bằng celluloza (xơ thô), khác xơ tiêu hóa của USDA, nên để ở
--    cột riêng fiber_crude_g; fiber_g của các dòng này để NULL.
--  * Một số món có tổng acid béo lớn hơn lipid vì sách lấy hai số từ hai tài liệu khác
--    nhau; giữ nguyên như sách.
--  * id = 900000000 + mã số trong sách (fdcId của USDA đều nhỏ hơn 3.000.000).
-- =====================================================================

ALTER TABLE nutrition_foods ADD COLUMN waste_pct NUMERIC(5, 2);
ALTER TABLE nutrition_foods ADD COLUMN fiber_crude_g NUMERIC(10, 3);
COMMENT ON COLUMN nutrition_foods.waste_pct IS 'Ti le thai bo khi so che (%), neu nguon co';
COMMENT ON COLUMN nutrition_foods.fiber_crude_g IS 'Xo tho (celluloza). Khac xo tieu hoa (fiber_g) cua USDA';

-- Tên tiếng Việt viết thường, bỏ dấu, để tìm kiếm ("rau muong" -> "Rau muống").
-- translate() + lower() đều IMMUTABLE nên dùng được cho cột sinh tự động.
ALTER TABLE nutrition_foods ADD COLUMN search_vi TEXT GENERATED ALWAYS AS (
    lower(translate(name_vi,
        'àáảãạăằắẳẵặâầấẩẫậèéẻẽẹêềếểễệìíỉĩịòóỏõọôồốổỗộơờớởỡợùúủũụưừứửữựỳýỷỹỵđÀÁẢÃẠĂẰẮẲẴẶÂẦẤẨẪẬÈÉẺẼẸÊỀẾỂỄỆÌÍỈĨỊÒÓỎÕỌÔỒỐỔỖỘƠỜỚỞỠỢÙÚỦŨỤƯỪỨỬỮỰỲÝỶỸỴĐ',
        'aaaaaaaaaaaaaaaaaeeeeeeeeeeeiiiiiooooooooooooooooouuuuuuuuuuuyyyyydaaaaaaaaaaaaaaaaaeeeeeeeeeeeiiiiiooooooooooooooooouuuuuuuuuuuyyyyyd'))
) STORED;
CREATE INDEX idx_nutrition_food_search_vi_fts ON nutrition_foods USING GIN (to_tsvector('simple', coalesce(search_vi, '')));
CREATE INDEX idx_nutrition_food_source ON nutrition_foods (source);

-- 526 thực phẩm, 14 nhóm. Sinh tự động từ bản PDF của sách - KHÔNG sửa tay.
